<script setup lang="ts">
import {onMounted,ref} from 'vue';
import {useBusinessStore,businessApi} from '../../stores/business';
import type {NativePlan,NativeReceipt,NativeTaskDetail} from '@shared/business';
const props=defineProps<{scopeKey:string;taskId?:string;readonly?:boolean}>();
interface Check {id:string;label:string;note?:string;correctable:boolean;resourceKind:string;resourceId:string;field:string;before:unknown;expectedResourceVersion:string}
const business=useBusinessStore(),data=ref<{queriedAt:string;sourceRevision:string;checks:Check[];corrections:Array<{id:string;actorId:string;at:string;note:string;evidence:string;before:unknown;after:unknown}>;note:string}>(),selected=ref<Check>(),value=ref(''),note=ref(''),evidence=ref(''),plan=ref<NativePlan|null>(null),receipt=ref<NativeReceipt|null>(null),busy=ref(false),error=ref(''),edited=ref(false);
const payload=(b:Record<string,unknown>)=>({...b,scopeKey:props.scopeKey});
async function work(fn:()=>Promise<void>){if(business.scopeKey!==props.scopeKey||!business.connected)return;busy.value=true;error.value='';try{await fn();}catch(e){error.value=(e as Error).message;}finally{busy.value=false;}}
async function refresh(){const r=await businessApi<typeof data.value>('proxy/resource-health');if(business.scopeKey===props.scopeKey)data.value=r;if(props.taskId){const t=await businessApi<NativeTaskDetail>('proxy/tasks/'+props.taskId);plan.value=t.plan;receipt.value=t.receipt;}}
function choose(c:Check){selected.value=c;value.value='';note.value='';evidence.value='';plan.value=null;receipt.value=null;edited.value=false;}
async function prepare(){await work(async()=>{if(!selected.value)return;const after=['size','capacity'].includes(selected.value.field)?Number(value.value):value.value.trim().startsWith('[')?JSON.parse(value.value):value.value.split(/[,，、]/).map(s=>s.trim()).filter(Boolean);const r=await businessApi<{plan:NativePlan}>('proxy/workflow/preview',payload({kind:'resource.patch',resourceKind:selected.value.resourceKind,resourceId:selected.value.resourceId,field:selected.value.field,after,expectedResourceVersion:selected.value.expectedResourceVersion,note:note.value,evidence:evidence.value}));plan.value=r.plan;receipt.value=null;edited.value=false;});}
async function commit(){await work(async()=>{if(!plan.value||edited.value)return;const r=await businessApi<{receipt:NativeReceipt}>('proxy/plans/commit',payload({planId:plan.value.id,version:plan.value.version}));receipt.value=r.receipt;plan.value=(await businessApi<{plan:NativePlan}>('proxy/plans/'+plan.value.id)).plan;await refresh();});}
onMounted(()=>void work(refresh));
</script>
<template><section class="native-card" data-view="health" aria-label="资源数据健康"><div class="native-card__head"><b>资源数据健康</b><button :disabled="busy" @click="work(refresh)">重新诊断</button></div><p>{{data?.note}}</p><p class="native-card__source">{{data?.queriedAt}} · {{data?.sourceRevision}}</p><div v-for="c in data?.checks||[]" :key="c.id" class="object-row"><b>{{c.label}}</b><p>{{c.id}} · {{c.note}}</p><button v-if="c.correctable&&!readonly" :disabled="busy" @click="choose(c)">填写已核实数据</button></div><p v-if="data&&!data.checks.length">当前检查范围未发现缺失或冲突。此结果不代表现场设备已核验。</p>
 <form v-if="selected&&!readonly" class="native-form" @submit.prevent="prepare"><p class="wide">{{selected.label}} · 原值 {{JSON.stringify(selected.before)}}</p><label class="wide">核实后值<input aria-label="资源核实后值" v-model="value" required @input="edited=true" placeholder="人数/容量填整数；设备填明确名称，确认无需求时填[]"></label><label class="wide">修正说明<textarea aria-label="资源修正说明" v-model="note" required @input="edited=true"></textarea></label><label class="wide">数据依据<textarea aria-label="资源数据依据" v-model="evidence" required @input="edited=true" placeholder="填写核对记录、资料编号或现场确认来源"></textarea></label><button :disabled="busy">准备原始数据修正</button></form>
 <div v-if="plan" class="native-confirm"><b>受控修正方案 · {{plan.id}}</b><p>{{plan.payload.resourceKind}} {{plan.payload.resourceId}} · {{plan.payload.field}}</p><p>{{JSON.stringify(plan.payload.before)}} → {{JSON.stringify(plan.payload.after)}}</p><p>{{plan.payload.note}} · 管理员声明依据：{{plan.payload.evidence}}</p><button v-if="!readonly" data-native-confirm :disabled="busy||edited||plan.state!=='awaiting_confirmation'" @click="commit">本人确认资源修正到原系统</button></div><div v-if="receipt" class="native-receipt">原系统回执 {{receipt.operationId}}</div><details v-if="data?.corrections.length"><summary>原始数据修正历史</summary><p v-for="c in data.corrections" :key="c.id">{{c.id}} · {{c.actorId}} · {{c.at}} · {{JSON.stringify(c.before)}} → {{JSON.stringify(c.after)}} · {{c.note}} · {{c.evidence}}</p></details><p v-if="error" role="alert" class="native-card__warn">{{error}}</p>
 </section></template>
